CREATE TABLE user_levels(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE,name VARCHAR(50),sort_order INT DEFAULT 0);
CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(190) UNIQUE,password VARCHAR(255),phone VARCHAR(30),role ENUM('user','admin') DEFAULT 'user',level_id INT,balance DECIMAL(18,2) DEFAULT 0,status ENUM('active','disabled') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(level_id) REFERENCES user_levels(id));
CREATE TABLE products(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),code VARCHAR(80) UNIQUE,description TEXT,provider_type ENUM('manual','ceirgo') DEFAULT 'manual',provider_service_id VARCHAR(100),provider_service_code VARCHAR(100),provider_cost DECIMAL(18,2) DEFAULT 0,whatsapp_group_id VARCHAR(100),ceir_check_enabled TINYINT(1) DEFAULT 1,auto_refund TINYINT(1) DEFAULT 1,is_active TINYINT(1) DEFAULT 1,processing_time VARCHAR(100),sort_order INT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE product_prices(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT,level_id INT,price DECIMAL(18,2),UNIQUE(product_id,level_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(level_id) REFERENCES user_levels(id));
CREATE TABLE orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(50) UNIQUE,user_id BIGINT,product_id BIGINT,imei CHAR(15),status ENUM('pending','ceir_check','processing','success','rejected','refunded','cancelled') DEFAULT 'pending',selling_price DECIMAL(18,2),provider_cost DECIMAL(18,2) DEFAULT 0,provider_type VARCHAR(30),provider_order_id VARCHAR(100),provider_response JSON NULL,wa_group_id VARCHAR(100),wa_message_id VARCHAR(190),ceir_status VARCHAR(30),ceir_raw_response JSON,refund_status ENUM('none','refunded') DEFAULT 'none',reject_reason VARCHAR(255) NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,processed_at DATETIME NULL,completed_at DATETIME NULL,INDEX(imei),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE order_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT,event VARCHAR(80),message TEXT,meta JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE transactions(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,type VARCHAR(40),reference VARCHAR(100),idempotency_key VARCHAR(190) NULL UNIQUE,amount DECIMAL(18,2),balance_before DECIMAL(18,2),balance_after DECIMAL(18,2),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(reference));
CREATE TABLE deposits(id BIGINT AUTO_INCREMENT PRIMARY KEY,deposit_number VARCHAR(50) UNIQUE,user_id BIGINT,gateway ENUM('manual','gobiz','jago'),amount DECIMAL(18,2),status ENUM('pending','paid','rejected','expired') DEFAULT 'pending',provider_reference VARCHAR(190),idempotency_key VARCHAR(190) NULL UNIQUE,proof_path VARCHAR(255),raw_payload JSON NULL,expires_at DATETIME,settled_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE tickets(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,subject VARCHAR(190),status ENUM('open','answered','closed') DEFAULT 'open',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ticket_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT,user_id BIGINT,message TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_keys(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,key_hash CHAR(64),label VARCHAR(100),is_active TINYINT(1) DEFAULT 1,last_used_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(`key` VARCHAR(100) PRIMARY KEY,`value` LONGTEXT);
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NULL,event VARCHAR(100),ip VARCHAR(45),meta JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_gateways(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE,name VARCHAR(80),is_active TINYINT(1) DEFAULT 0,config_json JSON NULL,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE provider_services(id BIGINT AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(30),provider_service_id VARCHAR(100),code VARCHAR(100),name VARCHAR(190),description TEXT,provider_price DECIMAL(18,2) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,raw_json JSON NULL,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(provider,code));
CREATE TABLE bot_settings(`key` VARCHAR(100) PRIMARY KEY,`value` LONGTEXT);
CREATE TABLE payment_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,gateway VARCHAR(30),external_id VARCHAR(190),amount DECIMAL(18,2),payload JSON,matched_deposit_id BIGINT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(gateway,external_id));
CREATE TABLE api_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NULL,endpoint VARCHAR(190),method VARCHAR(10),status_code INT,ip VARCHAR(45),created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
INSERT INTO user_levels(code,name,sort_order) VALUES ('user','User',1),('seller','Seller',2),('reseller','Reseller',3),('grosir','Grosir',4),('distributor','Distributor',5);
INSERT IGNORE INTO payment_gateways(code,name,is_active) VALUES ('manual','Manual Transfer',1),('gobiz','QRIS GoBiz',0),('jago','Bank Jago',0);
